def is_nested(string):
    stack = []
    for i, char in enumerate(string):
        if char == '[':
            stack.append(i)
        elif char == ']':
            if stack:
                stack.pop()
            else:
                return False
    if stack:
        return False
    # Check if there is at least one nested bracket
    nested = False
    for i in range(len(stack) - 1):
        if stack[i] < stack[i + 1]:
            nested = True
            break
    return nested
